head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isUpdate = false;
scwin.storageId = "";

// 수정 여부

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS04080.xml";
                scwin.storageId = $c.data.getParameter("storageId");

                // 시장구분코드, 용도구분
                const list = ["LD_MKT_TP_CD", "EDIT_USE_TP_CD"];
                const params = {"cdEngNmList":list};

                // 코드 정보 조회
                $c.sbm.execute(sbm_code, params);
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.ibx_editClssCd_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_editClssCd);
                // 양수만 되게 수정
                ibx_editClssCd.setValue((ibx_editClssCd.getValue()).replace(/[^0-9]/g, ""));
            };

            scwin.ibx_editClssEngNm_onkeyup = function (e) {

                $c.tms.disableBlockKor(ibx_editClssEngNm);
            };

            scwin.btn_save_onclick = async function (e) {

                // validation 체크
                if (!$c.tms.validateGroupTms("grp_input")) return;

                if (scwin.isUpdate) {                                           
                    $c.sbm.setAction(sbm_save, "/api/code/edit-upclss/update/" + dma_save.get("editUpclssCd"));
                }
                // 이중 클릭 방지
                btn_save.setDisabled(true);
                // 코드 정보 저장
                $c.sbm.execute(sbm_save, dma_save.getJSON());                
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_code_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {                    
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                    $c.tms.setSelectData(result.body, sbx_editUseTpCd, "cdValNm", "cdVal", "EDIT_USE_TP_CD", "cdEngNm");
                } else {
                    $c.win.alert(result.message);
                }

                setTimeout(function () {
                    const editClssCd = $c.data.getParameter("editClssCd");                
                    if (!$c.util.isEmpty(editClssCd)) {
                        dma_save.set("editUpclssCd", editClssCd);
                        dma_save.set("ldMktTpCd", $c.data.getParameter("ldMktTpCd"));
                        dma_save.set("editUseTpCd", $c.data.getParameter("editUseTpCd"));
                        dma_save.set("editUpclssNm", $c.data.getParameter("editClssNm"));
                        dma_save.set("editUpclssEngNm", $c.data.getParameter("editClssEngNm"));

                        ibx_editClssCd.setDisabled(true);
                        btn_save.setValue("변경 저장");
                        scwin.isUpdate = true;
                    }
                }, 100);
            };

            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    let params = {};
                    params.refreshYn = "Y";
                    params.storageId = scwin.storageId;

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
                // 이중 클릭 해제
                btn_save.setDisabled(false);
            }
